	let i=0
	let cnt=1; //그리드 칼럼 수 카운트용
	scwin.gridView1_subtotalStyleFormatter = function(value, formattedValue, subtotalColumnId) { // value : 원본 데이터 formattedValue : 형태가 적용된 데이터 subtotalColumnId : 부분합 컬럼명
		debugger;
		if (subtotalColumnId !=="column13" && subtotalColumnId !=="column11") {
        return "w2subtotaldefault";
		}
		const str = gridView1._getExcelSubtotalData(); // gridView1 subtotal 값 전제 스트링 가져오기
	//	console.log(str)

		//string->array 변환
		const resultArray = str.replace(/"/g, '').split(',').map(val => val === '' ? '' : Number(val));
	//	console.log(resultArray);

			// 서브토탈 row별 값 리턴해서 비교하기
			// 5개씩 자르기 : mf_gridView1.getColumnCount();-> row당 칼럼 5개
			const group = resultArray.slice(i, i + 5); 

			//Object.keys(mf_gridView1.subtotalObj.col5).length = 2 
			//column11, column13에서만 서브토탈 데이터 표기하고 있어서 2로 연산
			if(cnt>1&&cnt%2==1){ 
			i=i+5;
			}

			// 원본 데이터와 배열 내 최대값 비교
			for (let j = 0; j < group.length; j++) 
			{

				// if (Math.max(...group)===value) 
				// 	{	
				// 		cnt++;
				// 		return "w2subtotalplus";
				// 	} 
				// 	else{
				// 		cnt++;
	        	// 		return "w2subtotalminus";
	    		// } 

				switch (Math.max(...group) === value) {
					case true:
					cnt++;
					return "w2subtotalplus";
					case false:
					cnt++;
					return "w2subtotalminus";
}



			}
	//		}
}





